  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75)*40, 0.05, 2.8],
    [200+Math.sin(t*0.25+4)*100, 220+Math.cos(t*0.45+3)*70, 0.09, 1.6],
    [300+Math.cos(t*0.7+5)*80, 30+Math.sin(t*0.5+2)*50, 0.13, 1.4]
  ];
  let aS = 0, iS = 0, aS2 = 0, iS2 = 0;
  const n = src.length;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS2 += Math.cos(d*f*1.3 - t*sp*0.8 + 0.7);
    iS2 += Math.cos(d*f*0.5 + t*sp*0.4 + 2.1);
  }
  const act = aS/n, inh = iS/n, act2 = aS2/n, inh2 = iS2/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1) + Math.sin(sx*0.06+sy*0.01-t*0.6) + Math.sin(-sx*0.02+sy*0.05+t*0.9))/4 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin((sx*0.5-sy)*0.08+t*1.8)*0.15;
