  const crossR = Math.tanh((act*act2 - inh*inh2*0.5)*1.8);
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + crossR*0.3)*2.2);
  const reaction2 = Math.tanh((act2 - inh2*0.6 + bg*0.2 - spiral*0.5)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3 + Math.cos((sx-sy*0.5)*0.11-t*0.5)*0.2)*1.5)*0.3;
  const pulse = 0.85 + Math.sin(t*0.4)*0.1 + Math.sin(t*0.7+1)*0.05;
  const blend = reaction*0.55 + reaction2*0.2 + cell*0.15 + crossR*0.1;
  const v = blend*pulse*0.5 + 0.5;
  const pal = [[5,12,45],[12,50,85],[18,95,105],[25,140,130],[160,190,60],[220,175,50],[230,120,55],[195,60,60],[140,35,75],[80,25,90],[35,18,65],[5,12,45]];
